export function getAttaccanteByNome(nome) {
  return ATTACCANTI.find((a) => a.nome === nome);
}

export function getAttaccanteById(id) {
  return ATTACCANTI.find((a) => a.id === id);
}

export function getAttaccantiByFascia(fascia) {
  return ATTACCANTI.filter((a) => a.fascia === fascia);
}

export function getAttaccantiByTag(tag) {
  return ATTACCANTI.filter((a) => a.tags && a.tags.includes(tag));
}
